custom_qss:
/* MONO — pure grayscale. Every colour satisfies r==g==b; states are
   distinguished by lightness alone, never hue. The only preset with zero hue.
   Sharp corners, hairline rules, no translucency. */

* {
    border: none;
    background-color: transparent !important;
    color: #c8c8c8 !important;
}

QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent !important;
    border: none;
}

/* window: neutral ramp, light at top, no colour cast whatsoever */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #1a1a1a, stop:0.5 #121212, stop:1 #0c0c0c) !important;
    border-top: 1px solid #3a3a3a;
}
QDialog {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #1a1a1a, stop:1 #0c0c0c) !important;
    border-top: 1px solid #3a3a3a;
}

QMenuBar { background: transparent !important; }
QMenuBar::item {
    padding: 5px 12px;
    border-radius: 2px;
    background: transparent !important;
    color: #8a8a8a !important;
}
QMenuBar::item:selected { background: #3a3a3a !important; color: #f0f0f0 !important; }
QMenuBar::item:disabled { color: #4a4a4a !important; }

QMenu {
    background: #141414 !important;
    border: 1px solid #3a3a3a;
    border-radius: 2px;
    padding: 4px;
}
QMenu::item {
    padding: 5px 22px 5px 12px;
    border-radius: 2px;
    background: transparent !important;
    color: #c8c8c8 !important;
}
QMenu::item:selected { background: #4a4a4a !important; color: #ffffff !important; }
QMenu::item:disabled { color: #4a4a4a !important; }
QMenu::separator { height: 1px; background: #2a2a2a; margin: 4px 6px; }
QMenu::icon { padding-left: 4px; }

QToolBar { background: transparent !important; spacing: 2px; padding: 3px; }
QToolBar::separator { background: #2a2a2a; width: 1px; margin: 5px 3px; }
QToolBar QToolButton {
    background: transparent !important;
    padding: 4px 7px;
    border-radius: 2px;
    color: #8a8a8a !important;
}
QToolBar QToolButton:hover { background: #2a2a2a !important; color: #e8e8e8 !important; }
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: #4a4a4a !important;
    color: #ffffff !important;
}
QToolBar QToolButton:disabled { color: #3a3a3a !important; }

QToolButton {
    background: transparent !important;
    padding: 4px 7px;
    border-radius: 2px;
    color: #8a8a8a !important;
}
QToolButton:hover { background: #2a2a2a !important; color: #e8e8e8 !important; }
QToolButton:checked, QToolButton:pressed {
    background: #4a4a4a !important;
    color: #ffffff !important;
}
QToolButton:disabled { color: #3a3a3a !important; }

QPushButton {
    background: #1c1c1c !important;
    border: 1px solid #2a2a2a;
    border-radius: 2px;
    padding: 5px 16px;
    color: #c8c8c8 !important;
}
QPushButton:hover {
    background: #303030 !important;
    border: 1px solid #5a5a5a;
    color: #f0f0f0 !important;
}
QPushButton:pressed { background: #4a4a4a !important; color: #ffffff !important; }
QPushButton:checked {
    background: #4a4a4a !important;
    border: 1px solid #6a6a6a;
    color: #ffffff !important;
}
QPushButton:disabled {
    background: #141414 !important;
    border: 1px solid #222222;
    color: #3a3a3a !important;
}

QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background: #0e0e0e !important;
    border: 1px solid #2a2a2a;
    border-radius: 0px;
    padding: 4px 7px;
    color: #e0e0e0 !important;
    selection-background-color: #4a4a4a;
    selection-color: #ffffff;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus {
    border: 1px solid #6a6a6a;
    color: #ffffff !important;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled { color: #3a3a3a !important; }
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent !important; border: none; width: 15px;
}

QComboBox {
    background: #1c1c1c !important;
    border: 1px solid #2a2a2a;
    border-radius: 0px;
    padding: 4px 7px;
    color: #c8c8c8 !important;
}
QComboBox:hover { border: 1px solid #5a5a5a; }
QComboBox:focus { border: 1px solid #6a6a6a; }
QComboBox::drop-down { border: none; background: transparent !important; width: 16px; }
QComboBox QAbstractItemView {
    background: #141414 !important;
    border: 1px solid #4a4a4a;
    border-radius: 0px;
    padding: 3px;
    selection-background-color: #4a4a4a;
    selection-color: #ffffff;
}
QComboBox:disabled { color: #3a3a3a !important; }

QCheckBox, QRadioButton {
    color: #c8c8c8 !important;
    background: transparent !important;
    padding: 2px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 14px; height: 14px;
    background: #0e0e0e !important;
    border: 1px solid #2a2a2a;
    border-radius: 2px;
}
QRadioButton::indicator { border-radius: 7px; }
QCheckBox::indicator:hover, QRadioButton::indicator:hover { border: 1px solid #5a5a5a; }
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: #6a6a6a !important;
    border: 1px solid #8a8a8a;
}
QCheckBox:disabled, QRadioButton:disabled { color: #3a3a3a !important; }

/* tabs: no radius, lightness-only state */
QTabBar { background: transparent !important; }
QTabBar::tab {
    background: transparent !important;
    color: #7a7a7a !important;
    padding: 6px 16px;
    margin: 0 1px;
    border-radius: 2px 2px 0 0;
}
QTabBar::tab:hover { color: #c8c8c8 !important; background: #1c1c1c !important; }
QTabBar::tab:selected {
    background: #2a2a2a !important;
    color: #ffffff !important;
}
QTabBar::tab:disabled { color: #333333 !important; }
QTabBar::close-button { background: transparent !important; border: none; }
QTabBar::close-button:hover { background: #4a4a4a !important; }
QTabWidget::pane { border: 1px solid #222222; background: transparent !important; }

QDockWidget { background: transparent !important; border: none; }
QDockWidget::title {
    background: #161616 !important;
    border: none;
    border-bottom: 1px solid #2a2a2a;
    border-left: 3px solid #6a6a6a;
    padding: 6px 9px;
    color: #d0d0d0 !important;
    font-weight: 600;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent !important; border: none; padding: 2px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover {
    background: #3a3a3a !important;
}

QGroupBox {
    background: transparent !important;
    border: none;
    border-bottom: 1px solid #222222;
    margin-top: 14px;
    padding-top: 6px;
    font-weight: 600;
    color: #c8c8c8 !important;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 6px;
    background: transparent !important;
    color: #8a8a8a !important;
}

QAbstractItemView {
    background: #0e0e0e !important;
    border: 1px solid #222222;
    border-radius: 2px;
    alternate-background-color: #141414;
    selection-background-color: #3a3a3a;
    selection-color: #ffffff;
    outline: none;
}
QAbstractItemView::item { padding: 3px; }
QAbstractItemView::item:hover { background: #1e1e1e !important; }
QAbstractItemView::item:selected {
    background: #3a3a3a !important;
    color: #ffffff !important;
    border-left: 3px solid #8a8a8a;
}
QAbstractItemView::item:selected:!active {
    background: #232323 !important;
    border-left: 3px solid #4a4a4a;
}
QTreeView::item, QTreeWidget::item, QTreeWidgetItem,
QTableView::item, QListView::item, QListWidget::item {
    background: transparent !important;
}

QHeaderView { background: transparent !important; border: none; }
QHeaderView::section {
    background: #161616 !important;
    border: none;
    border-bottom: 1px solid #2a2a2a;
    padding: 5px 7px;
    color: #8a8a8a !important;
    font-weight: 600;
}
QHeaderView::section:hover { color: #d0d0d0 !important; }

QScrollBar:vertical { background: transparent !important; width: 11px; margin: 2px; }
QScrollBar::handle:vertical {
    background: #3a3a3a !important;
    border-radius: 4px;
    min-height: 26px;
}
QScrollBar::handle:vertical:hover { background: #6a6a6a !important; }
QScrollBar::handle:vertical:pressed { background: #8a8a8a !important; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0; background: none; border: none;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background: transparent !important;
}
QScrollBar:horizontal { background: transparent !important; height: 11px; margin: 2px; }
QScrollBar::handle:horizontal {
    background: #3a3a3a !important;
    border-radius: 4px;
    min-width: 26px;
}
QScrollBar::handle:horizontal:hover { background: #6a6a6a !important; }
QScrollBar::handle:horizontal:pressed { background: #8a8a8a !important; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0; background: none; border: none;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background: transparent !important;
}
QScrollBar::corner { background: transparent !important; }

QSlider::groove:horizontal {
    background: #222222 !important;
    height: 4px; border-radius: 2px;
}
QSlider::sub-page:horizontal { background: #6a6a6a !important; border-radius: 2px; }
QSlider::add-page:horizontal { background: #222222 !important; border-radius: 2px; }
QSlider::handle:horizontal {
    background: #d8d8d8 !important;
    border-radius: 5px;
    width: 11px; margin: -5px 0;
}
QSlider::handle:horizontal:hover { background: #ffffff !important; }
QSlider::groove:vertical {
    background: #222222 !important;
    width: 4px; border-radius: 2px;
}
QSlider::sub-page:vertical { background: #6a6a6a !important; border-radius: 2px; }
QSlider::add-page:vertical { background: #222222 !important; border-radius: 2px; }
QSlider::handle:vertical {
    background: #d8d8d8 !important;
    border-radius: 5px;
    height: 11px; margin: 0 -5px;
}
QSlider::handle:vertical:hover { background: #ffffff !important; }

QProgressBar {
    background: #0e0e0e !important;
    border: 1px solid #2a2a2a;
    border-radius: 2px;
    text-align: center;
    color: #c8c8c8 !important;
    min-height: 15px;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #4a4a4a, stop:1 #8a8a8a) !important;
}

QStatusBar {
    background: transparent !important;
    border: none;
    border-top: 1px solid #2a2a2a;
    color: #7a7a7a !important;
}
QStatusBar::item { background: transparent !important; }
QStatusBar QLabel { color: #7a7a7a !important; }

QToolTip {
    background: #141414 !important;
    border: 1px solid #4a4a4a;
    border-radius: 2px;
    padding: 5px 8px;
    color: #e0e0e0 !important;
}

QSplitter { background: transparent !important; border: none; }
QSplitter::handle { background: transparent !important; }
QSplitter::handle:hover { background: #2a2a2a !important; }
